// Relocates the collision header's offsets into pointers.
void resolve_level_asset_block_pointers(char *p) {
    const int *q;
    int i;
    int *e;
    int cnt;

    if (*(int *)p != 0) {
        *coll_hit_result_a = (int)(p + *(int *)p);
    }
    if (*(int *)(p + 4) != 0) {
        q = (const int *)(p + *(int *)(p + 4));
        cnt = q[0];
        collision_header_entry_table = q;
        i = 0;
        if (cnt > 0) {
            e = (int *)q + 7;
            do {
                *e = (int)q + *e;
                e += 4;
                i++;
            } while (i < *q);
        }
    }
}
